const env = require('../config/env');

/**
 * Centralized Error Handling Middleware
 * Ensures consistent JSON error shape and suppresses stack traces in production.
 */
module.exports = function errorHandler(err, req, res, next) {
  // Handle JSON parse errors generated by express.json()
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      success: false,
      error: {
        code: 'BAD_REQUEST',
        message: 'Malformed JSON payload in request body',
        details: null,
      },
    });
  }

  // Handle CORS rejection errors
  if (err.message && err.message.includes('CORS')) {
    return res.status(403).json({
      success: false,
      error: {
        code: 'CORS_ERROR',
        message: err.message,
        details: null,
      },
    });
  }

  // Handle Zod schema validation errors
  if (err.name === 'ZodError') {
    const issues = err.issues || (Array.isArray(err.errors) ? err.errors : []);
    return res.status(400).json({
      success: false,
      error: {
        code: 'VALIDATION_ERROR',
        message: 'Invalid request payload',
        details: issues.map((e) => ({
          field: e.path.join('.'),
          message: e.message,
        })),
      },
    });
  }

  // Handle PostgreSQL unique constraint violation (duplicate key)
  if (err.code === '23505') {
    const isMappingDuplicate =
      (err.constraint && err.constraint.includes('patient_doctors')) ||
      (err.detail && err.detail.includes('patient_doctors'));

    return res.status(409).json({
      success: false,
      error: {
        code: isMappingDuplicate ? 'DUPLICATE_MAPPING' : 'EMAIL_EXISTS',
        message: isMappingDuplicate
          ? 'Patient is already assigned to this doctor'
          : 'Email is already registered',
        details: null,
      },
    });
  }

  // Handle PostgreSQL foreign key violation (conflict on delete or reference)
  if (err.code === '23503') {
    return res.status(409).json({
      success: false,
      error: {
        code: 'DELETE_CONFLICT',
        message: 'Cannot delete record: referenced by existing assignments or dependencies',
        details: null,
      },
    });
  }


  const statusCode = err.statusCode || err.status || 500;
  const isProduction = (process.env.NODE_ENV || env.NODE_ENV) === 'production';

  // Do not expose stack traces or raw database error strings in production
  let message = err.message || 'An unexpected internal error occurred';
  if (statusCode === 500 && isProduction) {
    message = 'Internal server error';
  }

  const errorResponse = {
    success: false,
    error: {
      code: err.code || (statusCode === 500 ? 'INTERNAL_SERVER_ERROR' : 'ERROR'),
      message,
      details: err.details || null,
    },
  };

  // Only expose stack traces in non-production environments
  if (!isProduction && err.stack) {
    errorResponse.error.stack = err.stack;
  }

  return res.status(statusCode).json(errorResponse);
};
